anchor="function setLogoPreview(boxSelector,inputSelector,url,placeholder){const box=$(boxSelector),input=$(inputSelector);if(!box||!input)return;[...box.children].forEach(el=>{if(el!==input)el.remove()});const el=document.createElement(url?'img':'span');if(url){el.src=url;el.alt='Logo preview'}else el.textContent=placeholder;box.insertBefore(el,input)}\n"
helpers=anchor+'''function saveTakeoverReveal(company,logo){if(mode!=='takeover')return;const targets=selected.filter(n=>!own(spot(n))).map(n=>{const s=spot(n);return{spot_number:n,company_name:s.company_name||null,logo_url:s.logo_url||null}});if(!targets.length)return;try{localStorage.setItem('takeover_reveal_v1',JSON.stringify({targets,company_name:company,logo_url:logo||null,created_at:Date.now()}))}catch{}}\nfunction clearTakeoverReveal(){try{localStorage.removeItem('takeover_reveal_v1')}catch{}}\nfunction playTakeoverReveal(){let data=null;try{data=JSON.parse(localStorage.getItem('takeover_reveal_v1')||'null')}catch{};if(!data||!Array.isArray(data.targets)||!data.targets.length)return;if(Date.now()-Number(data.created_at||0)>3600000){clearTakeoverReveal();return}const stage=$('#takeoverRevealStage');if(!stage)return;stage.innerHTML='';data.targets.forEach((item,i)=>{const n=Number(item.spot_number),r=Math.floor((n-1)/4),c=(n-1)%4,card=document.createElement('div');card.className='takeover-reveal-card';card.style.left=(c*25)+'%';card.style.top=(r/3*100)+'%';card.style.width='25%';card.style.height=(100/3)+'%';card.style.setProperty('--reveal-delay',(i*90)+'ms');const old=item.logo_url?`<img src="${esc(item.logo_url)}" alt="">`:`<div class="wipe-wordmark">${esc(item.company_name||'AVAILABLE')}</div>`;card.innerHTML=`<div class="wipe-old">${old}<small>SPOT ${String(n).padStart(2,'0')}</small></div><div class="eraser-sweep"><i></i></div><div class="take-stamp">TAKEN</div>`;stage.appendChild(card)});stage.hidden=false;requestAnimationFrame(()=>requestAnimationFrame(()=>stage.classList.add('run')));setTimeout(()=>{stage.classList.remove('run');stage.hidden=true;stage.innerHTML='';clearTakeoverReveal()},2500)}\n'''
s=require_replace(s,anchor,helpers,'reveal helpers')
s=require_replace(s,'clearDraft();location.href=data.url','saveTakeoverReveal(company,selectedLogoUrl);clearDraft();location.href=data.url','save reveal before stripe')

pattern=r"async function renderAdmin\(\)\{.*?\}\n\$\('#saveConfig'\)"
replacement='''async function renderAdmin(){$('#startingPrice').value=config.starting_price;$('#minIncrement').value=config.min_increment;$('#purchasesEnabled').checked=!!config.purchases_enabled;$('#adminBoard').innerHTML=spots.map(s=>`<div class="admin-row"><span>${String(s.spot_number).padStart(2,'0')}</span><div><b>${esc(s.company_name||'AVAILABLE')} · ${s.current_price?cash(s.current_price):cash(config.starting_price)}</b><small>${s.website?esc(host(s.website)):'No owner'}</small></div><button class="tiny danger" data-reset="${s.spot_number}" ${s.owner_key?'':'disabled'}>RESET</button></div>`).join('');$$('[data-reset]').forEach(b=>b.onclick=()=>openModeration(Number(b.dataset.reset)));const [{data:attempts},{data:moderation}]=await Promise.all([sb.from('takeover_attempts').select('id,kind,status,company_name,total_amount,created_at').order('created_at',{ascending:false}).limit(20),sb.from('takeover_moderation_log').select('spot_number,previous_company_name,reason,note,created_at').order('created_at',{ascending:false}).limit(15)]);$('#adminAttempts').innerHTML=(attempts||[]).map(a=>`<div class="admin-row"><span>•</span><div><b>${esc(a.company_name)} · ${cash(a.total_amount)}</b><small>${a.kind} · ${a.status} · ${new Date(a.created_at).toLocaleString()}</small></div></div>`).join('')||'<div class="empty">No purchases yet.</div>';$('#adminModeration').innerHTML=(moderation||[]).map(m=>`<div class="admin-row moderation-row"><span>${String(m.spot_number).padStart(2,'0')}</span><div><b>${esc(m.previous_company_name||'Unknown advertiser')}</b><small>${esc(moderationReasonLabel(m.reason))} · ${new Date(m.created_at).toLocaleString()}</small>${m.note?`<p>${esc(m.note)}</p>`:''}</div></div>`).join('')||'<div class="empty">No moderation resets. Good.</div>'}\n$('#saveConfig')'''
s2,n=re.subn(pattern,replacement,s,count=1,flags=re.S)
if n!=1: raise SystemExit(f'render admin match count {n}')
