pattern=r"async function clearAdminSpot\(n\)\{.*?\}\n\nasync function handleReturn"
replacement='''let moderationSpot=null;\nfunction moderationReasonLabel(reason){return({fraud_or_scam:'Fraud or scam',malware_or_phishing:'Malware / phishing',illegal_or_dangerous:'Illegal / clearly dangerous',impersonation_or_rights:'Impersonation / serious rights abuse',credible_safety_or_legal_risk:'Credible safety / legal risk',other_extreme_issue:'Other extreme issue'})[reason]||'Moderation reset'}\nfunction openModeration(n){const s=spot(n);if(!s?.owner_key)return toast('That spot is already available');moderationSpot=n;$('#moderationTitle').textContent=`Reset Spot ${String(n).padStart(2,'0')}?`;$('#moderationReason').value='';$('#moderationNote').value='';openPanel('#moderationModal')}\n$('#moderationCancel').onclick=()=>{$('#moderationModal').classList.remove('on');moderationSpot=null};\n$('#confirmResetSpot').onclick=async()=>{if(!moderationSpot)return;const reason=$('#moderationReason').value,note=$('#moderationNote').value.trim();if(!reason)return toast('Choose a reset reason');if(reason==='other_extreme_issue'&&!note)return toast('Add a short note for Other');const b=$('#confirmResetSpot'),old=b.textContent;b.disabled=true;b.textContent='RESETTING…';const {error}=await sb.rpc('admin_reset_takeover_spot',{p_spot_number:moderationSpot,p_reason:reason,p_note:note||null});b.disabled=false;b.textContent=old;if(error)return toast(error.message);toast(`Spot ${moderationSpot} reset to available`);moderationSpot=null;$('#moderationModal').classList.remove('on');await refreshBoard();await renderAdmin()};\n\nasync function handleReturn'''
s2,n=re.subn(pattern,replacement,s,count=1,flags=re.S)
if n!=1: raise SystemExit(f'moderation function match count {n}')
s=s2

old="async function handleReturn(){const q=new URLSearchParams(location.search),state=q.get('takeover'),attempt=q.get('attempt');if(!state)return;if(state==='cancel')toast('Checkout cancelled — nothing changed');if(state==='success'){toast('Payment received — claiming your territory…');if(session&&attempt)await pollAttempt(attempt)}history.replaceState({},'',location.pathname)}\nasync function pollAttempt(id){for(let i=0;i<15;i++){const {data}=await sb.from('takeover_attempts').select('status,failure_reason').eq('id',id).maybeSingle();if(data?.status==='won'){toast('You own it. Welcome to the page.');clearDraft();await refreshBoard();return}if(data?.status==='refunded'){toast('The board changed during checkout. You were automatically refunded.');clearDraft();return}if(data?.status==='refund_failed'){toast('Payment needs review. No territory was assigned.');return}await new Promise(r=>setTimeout(r,900))}toast('Payment is still processing. Your account will update automatically.')}"
new="async function handleReturn(){const q=new URLSearchParams(location.search),state=q.get('takeover'),attempt=q.get('attempt');if(!state)return;if(state==='cancel'){clearTakeoverReveal();toast('Checkout cancelled — nothing changed')}if(state==='success'){toast('Payment received — claiming your territory…');if(session&&attempt)await pollAttempt(attempt)}history.replaceState({},'',location.pathname)}\nasync function pollAttempt(id){for(let i=0;i<15;i++){const {data}=await sb.from('takeover_attempts').select('status,failure_reason').eq('id',id).maybeSingle();if(data?.status==='won'){toast('You own it. Watch the board.');clearDraft();await refreshBoard();playTakeoverReveal();return}if(data?.status==='refunded'){clearTakeoverReveal();toast('The board changed during checkout. You were automatically refunded.');clearDraft();return}if(data?.status==='refund_failed'){clearTakeoverReveal();toast('Payment needs review. No territory was assigned.');return}await new Promise(r=>setTimeout(r,900))}toast('Payment is still processing. Your account will update automatically.')}"
s=require_replace(s,old,new,'return animation')
